Here's a complete example of a **Discord bot using Discord.js v14** that includes a **single slash command: `ban`**. This bot will allow users to ban a member from the server using the `/ban` command, with an optional reason.

---

### ✅ Prerequisites

Make sure you have:

- Node.js (v16 or higher)
- Discord.js v14 installed

You can install Discord.js using:

```bash
npm install discord.js
```

---

### 🧾 `index.js` (Main Bot File)

```js
const { Client, GatewayIntentBits, EmbedBuilder, PermissionsBitField } = require('discord.js');

// Create a new client
const client = new Client({
    intents: [
        GatewayIntentBits.Guilds,
        GatewayIntentBits.GuildMembers,
        GatewayIntentBits.GuildMessages,
        GatewayIntentBits.MessageContent
    ]
});

// Replace with your bot token
const TOKEN = 'YOUR_BOT_TOKEN_HERE';

// Command registration
client.on('ready', () => {
    console.log(`Logged in as ${client.user.tag}!`);

    // Register the /ban slash command
    client.commands = new Map();

    const banCommand = {
        name: 'ban',
        description: 'Ban a member from the server',
        options: [
            {
                name: 'user',
                description: 'The user to ban',
                type: 6, // User type
                required: true
            },
            {
                name: 'reason',
                description: 'The reason for the ban',
                type: 3, // String type
                required: false
            }
        ]
    };

    client.application.commands.create(banCommand);
});

// Handle slash commands
client.on('interactionCreate', async (interaction) => {
    if (!interaction.isCommand()) return;

    const { commandName, options } = interaction;

    if (commandName === 'ban') {
        const user = options.getUser('user');
        const reason = options.getString('reason') || 'No reason provided';

        // Check if the user has the permission to ban members
        if (!interaction.memberPermissions.has(PermissionsBitField.Flags.BanMembers)) {
            return interaction.reply({
                content: 'You don\'t have permission to ban members.',
                ephemeral: true
            });
        }

        // Check if the user is the same as the member who sent the command
        if (interaction.member.id === user.id) {
            return interaction.reply({
                content: 'You can\'t ban yourself.',
                ephemeral: true
            });
        }

        // Check if the user is a bot
        if (user.bot) {
            return interaction.reply({
                content: 'You can\'t ban a bot.',
                ephemeral: true
            });
        }

        // Check if the user is already banned
        try {
            const member = await interaction.guild.members.fetch(user.id);
            if (member.banned) {
                return interaction.reply({
                    content: 'That user is already banned.',
                    ephemeral: true
                });
            }
        } catch (error) {
            console.error('Error fetching user:', error);
            return interaction.reply({
                content: 'An error occurred while checking the user.',
                ephemeral: true
            });
        }

        // Ban the user
        try {
            await interaction.guild.members.ban(user, {
                reason: reason
            });

            // Create a response embed
            const embed = new EmbedBuilder()
                .setTitle('User Banned')
                .setDescription(`**${user.tag}** has been banned from the server.`)
                .setColor('#ff0000')
                .addFields([
                    { name: 'Reason', value: reason }
                ])
                .setTimestamp();

            await interaction.reply({ embeds: [embed] });
        } catch (error) {
            console.error('Error banning user:', error);
            await interaction.reply({
                content: 'An error occurred while banning the user.',
                ephemeral: true
            });
        }
    }
});

// Start the bot
client.login(TOKEN);
```

---

### 📝 Notes

- **Permissions**: The bot must have the `Ban Members` permission in the server.
- **Intents**: Make sure your bot has the right intents enabled in the **Developer Portal**.
- **Token**: Replace `'YOUR_BOT_TOKEN_HERE'` with your actual bot token.

---

### 🧪 To Test the Bot

1. Run the bot using:

```bash
node index.js
```

2. In your Discord server, type `/ban @user [reason]` to test the command.

